import { Button, Dialog } from '@jinx-ui/react';

interface DeleteProjectButtonProps {
  onConfirm: () => void;
}

export default function DeleteProjectButton({ onConfirm }: DeleteProjectButtonProps) {
  const [open, setOpen] = useState(false);

  const handleConfirm = () => {
    onConfirm();
    setOpen(false);
  };

  return (
    <Dialog.Root open={open} onOpenChange={setOpen}>
      <Dialog.Trigger asChild>
        <Button variant="danger">Удалить проект</Button>
